// Bollard UI — i18n-string-field · MIT licence · https://bollard-ui.vercel.app/components/i18n-string-field

/** Pure checks behind I18nStringField. Safe to run on the server or in CI. */

export interface PluralBlock {
  /** The counted argument, e.g. "count". */
  arg: string
  ordinal: boolean
  /** Branch keys in order, e.g. ["one", "other"] or ["=0", "other"]. */
  keys: string[]
  /** Text inside each branch. */
  bodies: string[]
  /** Offset of the block's opening brace. */
  start: number
  /** Offset just past the block's closing brace. */
  end: number
}

export interface TranslationIssue {
  kind: "placeholder" | "plural" | "length" | "untranslated"
  message: string
  /** One-tap fix: the whole corrected translation. */
  fix?: { label: string; value: string }
}

/** Every placeholder occurrence, normalised: {count}, {{name}}, %s, %1$s, <b>, </b>, <br/>. */
export function findPlaceholders(text: string): string[] {
  const out: string[] = []
  const rest = text.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, name: string) => {
    out.push(`{{${name}}}`)
    return " "
  })
  for (const m of rest.matchAll(/\{\s*(\w+)\s*(?=[,}])|%(?:\d+\$)?(?:\.\d+)?[sdif@]|<(\/?)([a-z][\w-]*|\d+)[^>]*?(\/?)>/gi)) {
    if (m[1]) out.push(`{${m[1]}}`)
    else if (m[0].startsWith("%")) out.push(m[0])
    else out.push(`<${m[2]}${m[3].toLowerCase()}${m[4]}>`)
  }
  return out
}

/** ICU `{arg, plural|selectordinal, …}` blocks, with their branches. */
export function pluralBlocks(text: string): PluralBlock[] {
  const blocks: PluralBlock[] = []
  for (const m of text.matchAll(/\{\s*(\w+)\s*,\s*(plural|selectordinal)\s*,/g)) {
    const block: PluralBlock = { arg: m[1], ordinal: m[2] === "selectordinal", keys: [], bodies: [], start: m.index, end: -1 }
    let i = m.index + m[0].length
    while (i < text.length) {
      const key = /^\s*(offset:\s*\d+\s*)?(=\d+|\w+)?\s*/.exec(text.slice(i))!
      i += key[0].length
      if (text[i] === "}" || i >= text.length) break
      if (text[i] !== "{") return blocks
      let depth = 1
      const start = ++i
      while (i < text.length && depth > 0) {
        if (text[i] === "{") depth++
        else if (text[i] === "}") depth--
        i++
      }
      block.keys.push(key[2] ?? "")
      block.bodies.push(text.slice(start, i - 1))
    }
    block.end = i + 1
    blocks.push(block)
  }
  return blocks
}

/** Plural categories a locale actually uses for whole numbers 0–1000 (French "many" only applies to millions). */
export function requiredPluralForms(locale: string, ordinal = false): string[] {
  const rules = new Intl.PluralRules(locale, { type: ordinal ? "ordinal" : "cardinal" })
  const used = new Set<string>(["other"])
  for (let n = 0; n <= 1000; n++) used.add(rules.select(n))
  return rules.resolvedOptions().pluralCategories.filter((c) => used.has(c))
}

/** Characters the string renders at: longest plural branch, tags removed, placeholders at a fixed width. */
export function renderedLength(text: string, placeholderLength = 4): number {
  let flat = text
  for (const block of pluralBlocks(text).reverse()) {
    const longest = block.bodies.reduce((a, b) => (b.length > a.length ? b : a), "")
    flat = flat.slice(0, block.start) + longest.replace(/#/g, "{n}") + flat.slice(block.end)
  }
  const width = "0".repeat(placeholderLength)
  flat = flat
    .replace(/\{\{\s*[\w.]+\s*\}\}|\{\s*\w+[^{}]*\}|%(?:\d+\$)?(?:\.\d+)?[sdif@]/g, width)
    .replace(/<[^>]+>/g, "")
  return [...flat].length
}

const count = (list: string[]) => list.reduce((m, t) => m.set(t, (m.get(t) ?? 0) + 1), new Map<string, number>())
const lang = (locale: string) => locale.toLowerCase().split(/[-_]/)[0]

/** Every problem with `translation` against `source`, most serious first. */
export function lintTranslation(
  source: string,
  translation: string,
  { locale, sourceLocale = "en", maxLength, placeholderLength = 4 }: { locale: string; sourceLocale?: string; maxLength?: number; placeholderLength?: number },
): { issues: TranslationIssue[]; length: number } {
  const issues: TranslationIssue[] = []
  const length = renderedLength(translation, placeholderLength)
  if (!translation.trim()) return { issues, length }

  // Placeholders: compare as sets so plural branches that repeat {name} don't count twice.
  const want = new Set(findPlaceholders(source))
  const have = new Set(findPlaceholders(translation))
  const missing = [...want].filter((t) => !have.has(t))
  const extra = [...have].filter((t) => !want.has(t))
  if (missing.length === 1 && extra.length === 1 && missing[0][0] === extra[0][0]) {
    const [from, to] = [extra[0], missing[0]]
    const inner = (t: string) => t.replace(/^\{+|\}+$/g, "")
    issues.push({
      kind: "placeholder",
      message: `${from} isn't in the source. It should stay ${to}.`,
      fix: { label: `Rename to ${to}`, value: translation.replace(new RegExp(`\\{(\\{?)\\s*${inner(from)}\\s*(?=[,}])`, "g"), `{$1${inner(to)}`) },
    })
  } else {
    for (const t of missing)
      issues.push({ kind: "placeholder", message: `Missing ${t}.`, fix: { label: `Add ${t}`, value: t.startsWith("</") ? translation.trimEnd() + t : `${translation.trimEnd()} ${t}` } })
    for (const t of extra) issues.push({ kind: "placeholder", message: `${t} isn't in the source.` })
  }
  // Tags opened but not closed (or the other way round) break the markup even when the set matches.
  const tags = count(findPlaceholders(translation).filter((t) => t.startsWith("<") && !t.endsWith("/>")))
  for (const [tag, n] of tags) {
    if (tag.startsWith("</")) continue
    const close = `</${tag.slice(1)}`
    const shortBy = n - (tags.get(close) ?? 0)
    if (shortBy > 0 && want.has(close) && have.has(close)) issues.push({ kind: "placeholder", message: `${tag} is opened ${n}× but closed ${n - shortBy}×.` })
  }

  // Plurals: the source's plural blocks must survive, with every form the target language needs.
  const srcBlocks = pluralBlocks(source)
  const blocks = pluralBlocks(translation)
  for (const src of srcBlocks) {
    const block = blocks.find((b) => b.arg === src.arg && b.ordinal === src.ordinal)
    if (!block) {
      issues.push({ kind: "plural", message: `The plural for {${src.arg}} is gone. Keep the keyword "${src.ordinal ? "selectordinal" : "plural"}" untranslated.` })
      continue
    }
    const need = requiredPluralForms(locale, block.ordinal).filter((c) => !block.keys.includes(c))
    if (!need.length) continue
    const other = block.bodies[block.keys.indexOf("other")] ?? block.bodies[block.bodies.length - 1] ?? ""
    const added = need.map((c) => ` ${c} {${other}}`).join("")
    const at = block.end - 1
    issues.push({
      kind: "plural",
      message: `${new Intl.DisplayNames([sourceLocale], { type: "language" }).of(locale) ?? locale} also needs “${need.join("”, “")}” for {${block.arg}}.`,
      fix: { label: `Add ${need.length === 1 ? "form" : "forms"}`, value: translation.slice(0, at).trimEnd() + added + translation.slice(at) },
    })
  }

  if (maxLength !== undefined && length > maxLength)
    issues.push({ kind: "length", message: `${length - maxLength} ${length - maxLength === 1 ? "character" : "characters"} over the ${maxLength}-character space.` })

  const strip = (s: string) =>
    s
      .replace(/\{\s*\w+\s*,\s*\w+\s*,|(?:=\d+|zero|one|two|few|many|other)\s*\{/g, " ")
      .replace(/\{\{?[^{}]*\}?\}|%(?:\d+\$)?(?:\.\d+)?[sdif@]|<[^>]+>|[{}#]/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase()
  if (lang(locale) !== lang(sourceLocale) && /\p{L}{3}/u.test(strip(source)) && strip(source) === strip(translation))
    issues.push({ kind: "untranslated", message: "This is still the source text." })

  return { issues, length }
}

"use client"

// Bollard UI — i18n-string-field · MIT licence · https://bollard-ui.vercel.app/components/i18n-string-field

import * as React from "react"
import { Languages, TriangleAlert, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { findPlaceholders, lintTranslation, type TranslationIssue } from "./i18n-checks"

export { findPlaceholders, lintTranslation, pluralBlocks, renderedLength, requiredPluralForms } from "./i18n-checks"
export type { TranslationIssue } from "./i18n-checks"

export interface I18nStringFieldProps
  extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange" | "maxLength"> {
  /** The source string, e.g. the English original. */
  source: string
  /** Target locale (BCP 47), used for plural rules and the label. */
  locale: string
  /** Locale of the source string. */
  sourceLocale?: string
  /** UI budget in rendered characters (tags don't count, placeholders count as `placeholderLength`). */
  maxLength?: number
  /** Width a placeholder is assumed to render at. */
  placeholderLength?: number
  /** Controlled translation. */
  value?: string
  /** Initial translation when uncontrolled. */
  defaultValue?: string
  /** Called with the translation on every change. */
  onValueChange?: (value: string) => void
  /** Visible label. `{language}` is filled in. */
  label?: string
  /** Label shown above the source string. */
  sourceLabel?: string
  /** Accessible label of the button that accepts a translation identical to the source. */
  keepSameLabel?: string
}

const fix =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

/**
 * A translation field that catches what reviewers miss because they read for
 * meaning: a dropped or renamed placeholder ({name} → {nom}), an unclosed <b>,
 * plural forms the target language needs (Polish has one, few, many, other),
 * copy that overflows its button, and source text pasted back untranslated.
 * Each placeholder chip on the source lights up once the translation carries
 * it, and most problems have a one-tap fix.
 */
export function I18nStringField({
  source,
  locale,
  sourceLocale = "en",
  maxLength,
  placeholderLength = 4,
  value,
  defaultValue = "",
  onValueChange,
  label = "Translation · {language}",
  sourceLabel = "Source",
  keepSameLabel = "It's meant to match the source",
  id,
  className,
  rows = 3,
  ...props
}: I18nStringFieldProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [sameOk, setSameOk] = React.useState(false)
  const autoId = React.useId()
  const fieldId = id ?? autoId
  const text = value ?? inner

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  const result = React.useMemo(
    () => lintTranslation(source, text, { locale, sourceLocale, maxLength, placeholderLength }),
    [source, text, locale, sourceLocale, maxLength, placeholderLength],
  )
  const issues = result.issues.filter((issue) => !(issue.kind === "untranslated" && sameOk))
  const language = new Intl.DisplayNames([sourceLocale], { type: "language" }).of(locale) ?? locale
  const tokens = [...new Set(findPlaceholders(source))]
  const present = new Set(findPlaceholders(text))
  const over = maxLength !== undefined && result.length > maxLength

  return (
    <div data-slot="i18n-string-field" className={cn("grid w-full max-w-md gap-1.5", className)}>
      <div className="rounded-md border bg-muted/50 px-3 py-2 text-sm">
        <p className="mb-1 text-xs font-medium text-muted-foreground">{sourceLabel}</p>
        <p className="leading-6 break-words whitespace-pre-wrap">{source}</p>
        {tokens.length > 0 && (
          <p className="mt-1.5 flex flex-wrap gap-1" aria-label="Placeholders the translation must keep">
            {tokens.map((token) => (
              <code
                key={token}
                data-present={present.has(token) || undefined}
                aria-label={`${token}: ${present.has(token) ? "present" : "missing"}`}
                className="rounded border border-amber-500/40 bg-amber-500/10 px-1 py-px font-mono text-xs text-amber-900 transition-colors duration-300 data-present:border-emerald-500/40 data-present:bg-emerald-500/10 data-present:text-emerald-800 dark:text-amber-200 dark:data-present:text-emerald-300"
              >
                {token}
              </code>
            ))}
          </p>
        )}
      </div>
      <label htmlFor={fieldId} className="mt-1.5 flex w-fit items-center gap-1.5 text-sm font-medium">
        <Languages aria-hidden className="size-4 text-muted-foreground" />
        {label.replace("{language}", `${language} (${locale})`)}
      </label>
      <textarea
        id={fieldId}
        lang={locale}
        rows={rows}
        value={text}
        spellCheck
        onChange={(event) => {
          setSameOk(false)
          update(event.target.value)
        }}
        aria-describedby={`${fieldId}-issues`}
        data-warning={issues.length ? "" : undefined}
        className="w-full min-w-0 resize-y rounded-md border bg-transparent px-3 py-2 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
        {...props}
      />
      <div className="flex items-start gap-3">
        <ul id={`${fieldId}-issues`} aria-live="polite" className="grid min-h-6 min-w-0 flex-1 gap-0.5 text-xs">
          {issues.map((issue) => (
            <li key={issue.kind + issue.message} className="flex gap-1.5 text-amber-700 dark:text-amber-400">
              <span className="flex h-6 shrink-0 items-center">
                <TriangleAlert aria-hidden className="size-3.5" />
              </span>
              <span className="flex min-w-0 flex-wrap items-center gap-x-2">
                <span className="py-1">{issue.message}</span>
                <IssueFix issue={issue} onApply={update} onKeepSame={() => setSameOk(true)} keepSameLabel={keepSameLabel} />
              </span>
            </li>
          ))}
        </ul>
        {maxLength !== undefined && (
          <div className="grid w-16 shrink-0 gap-1 pt-1.5 text-right text-xs tabular-nums" aria-label={`${result.length} of ${maxLength} characters`}>
            <span className={cn("text-muted-foreground", over && "font-medium text-amber-700 dark:text-amber-400")}>
              {result.length}/{maxLength}
            </span>
            <span className="h-1 overflow-hidden rounded-full bg-muted">
              <span
                className={cn("block h-full rounded-full bg-emerald-500 transition-[width,background-color] duration-300 ease-out", over && "bg-amber-500")}
                style={{ width: `${Math.min(100, (result.length / maxLength) * 100)}%` }}
              />
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

function IssueFix({ issue, onApply, onKeepSame, keepSameLabel }: { issue: TranslationIssue; onApply: (v: string) => void; onKeepSame: () => void; keepSameLabel: string }) {
  if (issue.kind === "untranslated")
    return (
      <button type="button" onClick={onKeepSame} aria-label={keepSameLabel} title={keepSameLabel} className="grid size-6 place-items-center rounded-md transition-colors hover:bg-amber-500/10 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
        <X aria-hidden className="size-3.5" />
      </button>
    )
  if (!issue.fix) return null
  const next = issue.fix.value
  return (
    <button type="button" onClick={() => onApply(next)} className={fix}>
      {issue.fix.label}
    </button>
  )
}
